PAYLOAD_B64=''
from pathlib import Path
import json,re,base64,gzip
root=Path('.')
www=root/'app/src/main/assets/www'
p=www/'content-data.js'
s=p.read_text()
m=re.search(r"window\.NS_CONTENT\s*=\s*(\{.*\});\s*\n\}\)\(\);?\s*$",s,re.S)
if not m: raise SystemExit('Cannot parse NS_CONTENT')
db=json.loads(m.group(1))
chg=json.loads(gzip.decompress(base64.b64decode(PAYLOAD_B64)).decode())
db['MEDICAL_SOURCES'].update(chg['sources'])
db['AUDIT_META']={'version':'v0.9-claim-audit','audited_at':'07.10.2026','scope':'Interna: 16 lekcji, 60 pytań, 30 fiszek','method':'Claim-by-claim review against current society guidelines, official standards and peer-reviewed/open academic references; textbooks used as secondary reference.','status':'Corrections applied after audit; see NurseStudy_Interna_Audit_v0.9.md for item-level statuses.'}
for subj,recs in chg['lessons'].items():
 arr=db['LESSONS'][subj]; by={x['id']:i for i,x in enumerate(arr)}
 for rid,obj in recs.items():
  if rid not in by: raise SystemExit(f'Lesson missing: {subj}/{rid}')
  arr[by[rid]]=obj
for field,key in [('QUESTIONS','questions'),('FLASHCARDS','flashcards')]:
 arr=db[field]; by={x['id']:i for i,x in enumerate(arr)}
 for rid,obj in chg[key].items():
  if rid not in by: raise SystemExit(f'{field} missing: {rid}')
  arr[by[rid]]=obj
p.write_text("/* NurseStudy content database — medically audited v0.9 (Interna). */\n(function(){\n  'use strict';\n  window.NS_CONTENT = "+json.dumps(db,ensure_ascii=False,indent=2)+";\n})();\n")
bg=root/'app/build.gradle'; bg.write_text(bg.read_text().replace('versionCode 8','versionCode 9').replace("versionName '0.8.0-test'","versionName '0.9.0-test'"))
sw=www/'sw.js'; sw.write_text(sw.read_text().replace('nursestudy-v8-interna','nursestudy-v9-interna-audit'))
rd=root/'README.md'; r=rd.read_text(); add='\n\n## v0.9 – audyt Interny 1:1\nInterna została poddana audytowi twierdzenie-po-twierdzeniu względem aktualnych wytycznych i źródeł naukowych. Poprawiono m.in. ESC HF 2026, precyzję antykoagulacji w AF, definicję hipoglikemii ADA 2026, CURB65, płynoterapię i źródła hematologiczne/endokrynologiczne.\n'; rd.write_text(r if '## v0.9 – audyt Interny 1:1' in r else r+add)
